-- Toggle Float: tiled -> float at 90% of the monitor, centered; floating -> back to tiled.
-- Pure Lua on purpose. Under hyprlang2lua, `hyprctl dispatch ...` is reinterpreted as
-- Lua (`hl.dispatch(...)`), so the old shell version below no longer works. Note the
-- native `resize` dispatcher wants NUMERIC pixels (not "90%" strings), so we compute
-- them from the focused monitor (width/scale) — this stays correct on any resolution.
hl.bind(
	mainMod .. " + D",
	function()
		local win = hl.get_active_window()
		if win and win.floating then
			hl.dispatch(hl.dsp.window.float())
		else
			local m = hl.get_active_monitor()
			hl.dispatch(hl.dsp.window.float())
			hl.dispatch(hl.dsp.window.resize({
				x = math.floor(m.width / m.scale * 0.9),
				y = math.floor(m.height / m.scale * 0.9),
			}))
			hl.dispatch(hl.dsp.window.center())
		end
	end,
	{ description = "Toggle Float" }
)

